{
  "ref": "spec:openapi",
  "content": {
    "format": "openapi-3.1",
    "title": "TerraPulse Networks \u2014 a precision-agriculture telemetry platform aggregating soil and weather sensor readings across thousands of field plots API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the TerraPulse Networks \u2014 a precision-agriculture telemetry platform aggregating soil and weather sensor readings across thousands of field plots API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "TerraPulse Networks \u2014 a precision-agriculture telemetry platform aggregating soil and weather sensor readings across thousands of field plots API",
        "version": "1.0.0",
        "description": "TerraPulse Field API: a REST service that ingests sensor readings from in-ground soil probes and exposes them via paginated query endpoints for downstream dashboards and analytics jobs."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc"
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/readings": {
          "get": {
            "summary": "List sensor readings (cursor pagination)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/readings": {
          "get": {
            "summary": "DEPRECATED legacy readings",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/plots": {
          "get": {
            "summary": "List plots (offset/limit pagination)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts": {
          "get": {
            "summary": "List alerts (Link-header RFC5988 pagination)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/summary": {
          "get": {
            "summary": "Regional rollup stats",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/diag/stream": {
          "get": {
            "summary": "Diagnostic cursor stream",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/probes": {
          "get": {
            "summary": "List probes",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
